            q = k % p
            if q in assignment and assignment[q] != v:
                valid = False
                break
            assignment[q] = v
        if valid and len(assignment) >= 3:
            period = p
            break

    seq = [None] * period
    for k, colors in marks.items():
        v = max(set(colors), key=colors.count)
        q = k % period
        if seq[q] is None:
            seq[q] = v

    known = [i for i, v in enumerate(seq) if v is not None]
    if not known:
        return [row[:] for row in grid]
    for i in range(period):
        if seq[i] is None:
            j = min(known, key=lambda x: min((i-x) % period, (x-i) % period))
