                    if other != color and is_frame(other, box)
                    and (box[1]-box[0]-1, box[3]-box[2]-1) == (ph, pw))
        if score and (best is None or score > best[0]):
            best = (score, color, patt)

    if best is None:
        return out
    _, source, pattern = best
    ph, pw = len(pattern), len(pattern[0])

    for color, (r0, r1, c0, c1) in boxes.items():
        if color == source or not is_frame(color, boxes[color]):
